// cycle detection, and minimal (dirty-only) recomputation.

export type CellValue = number | string | boolean | null;
export interface CycleError {
  error: 'CYCLE';
}
export interface Div0Error {
  error: 'DIV0';
}
export type EvalResult = Exclude<CellValue, null> | CycleError | Div0Error;

// ---------------------------------------------------------------- Tokenizer

type TokenType = 'num' | 'ref' | 'func' | 'range' | 'op' | 'lparen' | 'rparen' | 'comma';

interface Token {
  type: TokenType;
  value: string;
}

const CELL_REF = /^[A-Za-z]+[0-9]+/; // e.g. B2, AA10
const NUMBER = /^\d+(\.\d+)?/;
const FUNC_NAME = /^[A-Za-z]+(?=\s*\()/;
const RANGE_SEP = /:/;

function tokenize(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < src.length) {
    const ch = src[i];
    if (/\s/.test(ch)) {
      i++;
      continue;
    }
    const rest = src.slice(i);
    let m: RegExpMatchArray | null;
    if ((m = rest.match(NUMBER))) {
      tokens.push({ type: 'num', value: m[0] });
      i += m[0].length;
    } else if ((m = rest.match(CELL_REF))) {
      // "A1:B10" -> range token
      const afterIdx = i + m[0].length;
      const after = src.slice(afterIdx);
      if (RANGE_SEP.test(after[0] ?? '') && CELL_REF.test(after.slice(1).trimStart())) {
        const second = after.slice(1).trimStart().match(CELL_REF)![0];
        tokens.push({ type: 'range', value: `${m[0]}:${second}` });
        i = afterIdx + 1 + after.slice(1).trimStart().indexOf(second) + second.length;
      } else {
        tokens.push({ type: 'ref', value: m[0].toUpperCase() });
        i += m[0].length;
      }
    } else if ((m = rest.match(FUNC_NAME))) {
      tokens.push({ type: 'func', value: m[0].toUpperCase() });
      i += m[0].length;
    } else if ('+-*/'.includes(ch)) {
      tokens.push({ type: 'op', value: ch });
      i++;
    } else if (ch === '(') {
      tokens.push({ type: 'lparen', value: ch });
      i++;
    } else if (ch === ')') {
      tokens.push({ type: 'rparen', value: ch });
      i++;
    } else if (ch === ',') {
      tokens.push({ type: 'comma', value: ch });
      i++;
    } else {
      throw new Error(`Unexpected character '${ch}' at position ${i}`);
    }
  }
  return tokens;
}

// ------------------------------------------- AST + recursive-descent parser
// Grammar (standard precedence):
//   expr    := term (('+'|'-') term)*
//   term    := factor (('*'|'/') factor)*
//   factor  := NUMBER | cellref | func(args) | '(' expr ')'

type Node =
  | { kind: 'num'; value: number }
  | { kind: 'ref'; cell: string }
  | { kind: 'range'; start: string; end: string }
  | { kind: 'unary'; op: '-' | '+'; arg: Node }
  | { kind: 'bin'; op: '+' | '-' | '*' | '/'; left: Node; right: Node }
  | { kind: 'call'; fn: 'SUM' | 'AVG' | 'MIN' | 'MAX'; args: Node[] };

class Parser {
  private pos = 0;
  constructor(private readonly tokens: Token[]) {}

  parse(): Node {
    const node = this.expr();
    if (this.pos < this.tokens.length) throw new Error('Unexpected trailing input');
    return node;
  }

  private peek(): Token | undefined {
    return this.tokens[this.pos];
  }

  private expr(): Node {
    let left = this.term();
    while (this.peek()?.type === 'op' && '+-'.includes(this.peek()!.value)) {
      const op = this.tokens[this.pos++].value as '+' | '-';
      left = { kind: 'bin', op, left, right: this.term() };
    }
    return left;
  }

  private term(): Node {
    let left = this.unary();
    while (this.peek()?.type === 'op' && '*/'.includes(this.peek()!.value)) {
      const op = this.tokens[this.pos++].value as '*' | '/';
      left = { kind: 'bin', op, left, right: this.unary() };
    }
    return left;
  }

  private unary(): Node {
    const t = this.peek();
    if (t?.type === 'op' && (t.value === '-' || t.value === '+')) {
      this.pos++;
      return { kind: 'unary', op: t.value as '-' | '+', arg: this.unary() };
    }
    return this.primary();
  }

  private primary(): Node {
    const t = this.peek();
    if (!t) throw new Error('Unexpected end of formula');
    if (t.type === 'num') {
      this.pos++;
      return { kind: 'num', value: Number(t.value) };
    }
    if (t.type === 'ref') {
      this.pos++;
      return { kind: 'ref', cell: t.value };
    }
    if (t.type === 'range') {
      this.pos++;
      const [a, b] = t.value.split(':');
      return { kind: 'range', start: a.toUpperCase(), end: b.toUpperCase() };
    }
    if (t.type === 'func') {
      this.pos++;
      if (this.peek()?.type !== 'lparen') throw new Error(`Expected '(' after ${t.value}`);
      this.pos++; // consume (
      const args: Node[] = [];
      if (this.peek()?.type !== 'rparen') {
        args.push(this.arg());
        while (this.peek()?.type === 'comma') {
          this.pos++;
          args.push(this.arg());
        }
      }
      if (this.peek()?.type !== 'rparen') throw new Error(`Expected ')' to close ${t.value}(`);
      this.pos++;
      if (!['SUM', 'AVG', 'MIN', 'MAX'].includes(t.value)) {
        throw new Error(`Unknown function ${t.value}`);
      }
      return { kind: 'call', fn: t.value as 'SUM' | 'AVG' | 'MIN' | 'MAX', args };
    }
    if (t.type === 'lparen') {
      this.pos++;
      const inner = this.expr();
      if (this.peek()?.type !== 'rparen') throw new Error("Expected ')'");
      this.pos++;
      return inner;
    }
    throw new Error(`Unexpected token '${t.value}'`);
  }

  // An argument may be a plain expression or a bare range.
  private arg(): Node {
    const t = this.peek();
    if (t?.type === 'range') {
      this.pos++;
      const [a, b] = t.value.split(':');
      return { kind: 'range', start: a.toUpperCase(), end: b.toUpperCase() };
    }
    return this.expr();
  }
}

export function parseFormula(src: string): Node {
  const p = new Parser(tokenize(src));
  return p.parse();
}

function collectRefs(node: Node, into: Set<string>): void {
  switch (node.kind) {
    case 'ref':
      into.add(node.cell);
      break;
    case 'range':
      for (const c of expandRange(node.start, node.end)) into.add(c);
      break;
    case 'unary':
      collectRefs(node.arg, into);
      break;
    case 'bin':
      collectRefs(node.left, into);
      collectRefs(node.right, into);
      break;
    case 'call':
      for (const a of node.args) collectRefs(a, into);
      break;
  }
}

// --------------------------------------------------------- Cell coordinates

const COL_RE = /^([A-Z]+)([0-9]+)$/;

export function parseCellRef(ref: string): { col: number; row: number } {
  const m = ref.toUpperCase().match(COL_RE);
  if (!m) throw new Error(`Invalid cell reference: ${ref}`);
  let col = 0;
  for (const ch of m[1]) col = col * 26 + (ch.charCodeAt(0) - 64);
  return { col: col - 1, row: Number(m[2]) - 1 };
}

export function makeCellRef(col: number, row: number): string {
  let s = '';
  col += 1;
  while (col > 0) {
    const rem = (col - 1) % 26;
    s = String.fromCharCode(65 + rem) + s;
    col = Math.floor((col - 1) / 26);
  }
  return `${s}${row + 1}`;
}

export function expandRange(start: string, end: string): string[] {
  const a = parseCellRef(start);
  const b = parseCellRef(end);
  const cells: string[] = [];
  const minCol = Math.min(a.col, b.col), maxCol = Math.max(a.col, b.col);
  const minRow = Math.min(a.row, b.row), maxRow = Math.max(a.row, b.row);
  for (let r = minRow; r <= maxRow; r++) {
    for (let c = minCol; c <= maxCol; c++) cells.push(makeCellRef(c, r));
  }
  return cells;
}

// ------------------------------------------------------------ Sheet engine

interface Cell {
  raw: string; // raw user input ('' when empty)
  ast: Node | null;
  deps: Set<string>; // cells this cell reads from
  dependents: Set<string>; // cells that read from this cell
  value: EvalResult | undefined;
}

export interface Sheet {
  set(cellRef: string, raw: string): void;
  get(cellRef: string): EvalResult;
  getRecomputeCount(): number;
}

const CYCLE: CycleError = { error: 'CYCLE' };
const DIV0: Div0Error = { error: 'DIV0' };

export function createSheet(): Sheet {
  const cells = new Map<string, Cell>();

  function ensure(ref: string): Cell {
    ref = ref.toUpperCase();
    let c = cells.get(ref);
    if (!c) {
      c = { raw: '', ast: null, deps: new Set(), dependents: new Set(), value: undefined };
      cells.set(ref, c);
    }
    return c;
  }

  function isFormula(raw: string): boolean {
    return typeof raw === 'string' && raw.trimStart().startsWith('=');
  }

  function evaluate(node: Node, seen: Set<string>): EvalResult {
    switch (node.kind) {
      case 'num':
        return node.value;
      case 'ref': {
        const v = compute(node.cell, seen);
        if (typeof v === 'object' && v !== null && 'error' in v) return v;
        return typeof v === 'number' ? v : coerce(v);
      }
      case 'unary':
        return node.op === '-' ? -(evaluate(node.arg, seen) as number) : evaluate(node.arg, seen);
      case 'bin': {
        const l = toNum(evaluate(node.left, seen));
        const r = toNum(evaluate(node.right, seen));
        if (isErr(l)) return l;
        if (isErr(r)) return r;
        switch (node.op) {
          case '+': return l + r;
          case '-': return l - r;
          case '*': return l * r;
          case '/': return r === 0 ? DIV0 : l / r;
        }
        break;
      }
      case 'call': {
        const vals: number[] = [];
        for (const a of node.args) {
          if (a.kind === 'range') {
            for (const ref of expandRange(a.start, a.end)) {
              const v = compute(ref, seen);
              if (isErr(v)) return v;
              if (typeof v === 'number') vals.push(v);
              else if (v !== '' && v !== null && typeof v === 'number') vals.push(v);
              // non-numeric cells in ranges are ignored (spreadsheet semantics)
            }
          } else {
            const v = evaluate(a, seen);
            if (isErr(v)) return v;
            if (typeof v === 'number') vals.push(v);
          }
        }
        if (vals.length === 0) return 0;
        switch (node.fn) {
          case 'SUM': return vals.reduce((x, y) => x + y, 0);
          case 'AVG': return vals.reduce((x, y) => x + y, 0) / vals.length;
          case 'MIN': return Math.min(...vals);
          case 'MAX': return Math.max(...vals);
        }
        break;
      }
    }
    throw new Error('Unreachable');
  }

  function isErr(v: unknown): v is CycleError | Div0Error {
    return typeof v === 'object' && v !== null && 'error' in v;
  }

  function toNum(v: EvalResult): number | CycleError | Div0Error {
    if (isErr(v)) return v;
    if (typeof v === 'number') return v;
    if (typeof v === 'boolean') return v ? 1 : 0;
    if (v === '' || v === null) return 0;
    const n = Number(v);
    return Number.isNaN(n) ? 0 : n;
  }

  function coerce(v: Exclude<CellValue, null>): number {
    if (typeof v === 'number') return v;
    if (typeof v === 'boolean') return v ? 1 : 0;
    if (v === '') return 0;
    const n = Number(v);
    return Number.isNaN(n) ? 0 : n;
  }

  /**
   * Compute `ref` on demand. `seen` carries refs currently being computed
   * along this path; re-entering one means we found a cycle. Cells in a
   * cycle get CYCLE and are cached so healing works later.
   */
  function compute(ref: string, seen: Set<string>): EvalResult {
    ref = ref.toUpperCase();
    const cell = cells.get(ref);
    if (!cell || cell.raw === '') return '';
    if (cell.value !== undefined && !cell.ast) return cell.value; // literal cache
    if (cell.ast === null) return parseLiteral(cell.raw);

    if (seen.has(ref)) return CYCLE; // cycle found on this path

    seen.add(ref);
    const result = evaluate(cell.ast, seen);
    seen.delete(ref);

    // Cache only non-cycle results; cycle results must be recomputed so that
    // breaking the cycle can heal them.
    if (!(result as CycleError).error || (result as CycleError).error !== 'CYCLE') {
      cell.value = result;
    } else {
      cell.value = undefined; // don't cache CYCLE permanently
      markCycleMembersDirty(ref);
    }
    return result;
  }

  /** When a cycle is detected at `entry`, stamp every member with CYCLE. */
  function markCycleMembersDirty(entry: string): void {
    // Walk downstream from entry through dependents; any cell whose
    // evaluation leads back into the cycle gets the CYCLE value.
    const visiting = new Set<string>([entry]);
    const stack = [entry];
    const inCycle: string[] = [];
    while (stack.length) {
      const cur = stack.pop()!;
      for (const dep of cells.get(cur)?.dependents ?? []) {
        if (!visiting.has(dep)) {
          visiting.add(dep);
          stack.push(dep);
        }
      }
    }
    // Any visited cell that transitively depends on itself is part of / fed by
    // the cycle. To be precise: find actual members via self-reachability.
    for (const candidate of visiting) {
      if (reaches(candidate, candidate)) {
        inCycle.push(candidate);
        const c = ensure(candidate);
        c.value = CYCLE;
      }
    }
  }

  function reaches(from: string, target: string): boolean {
    // Does evaluating `from` require `target`? (i.e., target reachable from from's deps)
    const stack = [...cells.get(from)?.deps ?? []];
    const vis = new Set<string>([from]);
    while (stack.length) {
      const cur = stack.pop()!;
      if (cur === target) return true;
      if (vis.has(cur)) continue;
      vis.add(cur);
      for (const d of cells.get(cur)?.deps ?? []) stack.push(d);
    }
    return false;
  }

  let recomputeCount = 0;

  /** Recompute `ref` (and everything downstream), counting each cell computed. */
  function recomputeFrom(rootRef: string): void {
    recomputeCount = 0;
    const order: string[] = [];
    const vis = new Set<string>();
    // Collect dirty set: root + all transitive dependents.
    const stack = [rootRef];
    while (stack.length) {
      const cur = stack.pop()!;
      if (vis.has(cur)) continue;
      vis.add(cur);
      order.push(cur);
      for (const dep of cells.get(cur)?.dependents ?? []) stack.push(dep);
    }
    // Evaluate in dependency-safe order within the dirty set (topological).
    const done = new Set<string>();
    const computing = new Set<string>();
    const evalOne = (ref: string): EvalResult => {
      if (done.has(ref)) return cells.get(ref)!.value!;
      if (computing.has(ref)) {
        // genuine cycle among dirty cells
        for (const c of collectingCycle(computing)) {
          ensure(c).value = CYCLE;
          done.add(c);
        }
        return CYCLE;
      }
      computing.add(ref);
      const cell = ensure(ref);
      let result: EvalResult;
      if (cell.ast) result = evaluate(cell.ast, computing);
      else result = parseLiteral(cell.raw);
      computing.delete(ref);
      if (!(result as CycleError).error || (result as CycleError).error !== 'CYCLE') {
        cell.value = result;
      }
      done.add(ref);
      recomputeCount++;
      return result;
    };
    for (const ref of order) evalOne(ref);
  }

  function collectingCycle(inProgress: Set<string>): string[] {
    return [...inProgress];
  }

  const api: Sheet = {
    set(ref, raw) {
      ref = ref.toUpperCase();
      const cell = ensure(ref);

      // Remove old outgoing dependency edges.
      for (const d of cell.deps) cells.get(d)?.dependents.delete(ref);
      cell.deps.clear();

      cell.raw = raw;
      cell.value = undefined;
      if (isFormula(raw)) {
        try {
          cell.ast = parseFormula(raw.trimStart().slice(1));
        } catch {
          cell.ast = null;
          cell.value = '#PARSE_ERROR';
          recomputeFrom(ref);
          return;
        }
        collectRefs(cell.ast, cell.deps);
        for (const d of cell.deps) ensure(d).dependents.add(ref);
        recomputeFrom(ref);
      } else {
        cell.ast = null;
        recomputeFrom(ref);
      }
    },

    get(ref) {
      ref = ref.toUpperCase();
      const cell = cells.get(ref);
      if (!cell || cell.raw === '') return '';
      if (cell.value !== undefined) return cell.value;
      if (!cell.ast) return parseLiteral(cell.raw);
      // Lazily resolve (e.g., first read before any dependent chain ran).
      const result = compute(ref, new Set());
      if ((result as CycleError).error === 'CYCLE') {
        markCycleMembersDirty(ref);
      }
      return result;
    },

    getRecomputeCount() {
      return recomputeCount;
    },
  };

  return api;
}

function parseLiteral(raw: string): EvalResult {
  const trimmed = raw.trim();
  if (trimmed === '') return '';
  if (/^-?\d+(\.\d+)?$/.test(trimmed)) return Number(trimmed);
  if (trimmed.toLowerCase() === 'true') return true;
  if (trimmed.toLowerCase() === 'false') return false;
  return trimmed;
}
