  | { kind: 'ref'; cell: string }
  | { kind: 'range'; start: string; end: string }
  | { kind: 'unary'; op: '-' | '+'; arg: Node }
  | { kind: 'bin'; op: '+' | '-' | '*' | '/'; left: Node; right: Node }
  | { kind: 'call'; fn: 'SUM' | 'AVG' | 'MIN' | 'MAX'; args: Node[] };

const FUNCTIONS = new Set(['SUM', 'AVG', 'MIN', 'MAX']);

