  private pos = 0;
  constructor(private readonly tokens: Token[]) {}

  parse(): Node {
    const node = this.expr();
    if (this.pos < this.tokens.length) throw new Error(`Unexpected token '${this.tokens[this.pos].value}'`);
    return node;
  }

  private peek(): Token | undefined {
    return this.tokens[this.pos];
  }

  private expr(): Node {
    let left = this.term();
    while (this.peek()?.type === 'op' && '+-'.includes(this.peek()!.value)) {
      const op = this.tokens[this.pos++].value as '+' | '-';
      left = { kind: 'bin', op, left, right: this.term() };
    }
    return left;
  }

  private term(): Node {
    let left = this.unary();
    while (this.peek()?.type === 'op' && '*/'.includes(this.peek()!.value)) {
      const op = this.tokens[this.pos++].value as '*' | '/';
      left = { kind: 'bin', op, left, right: this.unary() };
    }
    return left;
  }

  private unary(): Node {
    const t = this.peek();
    if (t?.type === 'op' && (t.value === '-' || t.value === '+')) {
      this.pos++;
      return { kind: 'unary', op: t.value as '-' | '+', arg: this.unary() };
    }
    return this.primary();
  }

  private primary(): Node {
    const t = this.peek();
    if (!t) throw new Error('Unexpected end of formula');
    switch (t.type) {
      case 'num':
        this.pos++;
        return { kind: 'num', value: Number(t.value) };
      case 'ref':
        this.pos++;
        return { kind: 'ref', cell: t.value };
      case 'func': {
        this.pos++;
        if (this.peek()?.type !== 'lparen') throw new Error(`Expected '(' after ${t.value}`);
        this.pos++;
        const args: Node[] = [];
        if (this.peek()?.type !== 'rparen') {
          args.push(this.arg());
          while (this.peek()?.type === 'comma') {
            this.pos++;
            args.push(this.arg());
          }
        }
        if (this.peek()?.type !== 'rparen') throw new Error(`Expected ')' to close ${t.value}(…)`);
        this.pos++;
        if (!FUNCTIONS.has(t.value)) throw new Error(`Unknown function ${t.value}`);
        return { kind: 'call', fn: t.value as 'SUM' | 'AVG' | 'MIN' | 'MAX', args };
      }
      case 'lparen': {
        this.pos++;
        const inner = this.expr();
        if (this.peek()?.type !== 'rparen') throw new Error("Expected ')'");
        this.pos++;
        return inner;
      }
      default:
        throw new Error(`Unexpected token '${t.value}'`);
    }
  }

  // An argument may be a bare range (e.g. SUM(A1:A10)) or an expression.
  private arg(): Node {
    const t = this.peek();
    if (t?.type === 'range') {
      this.pos++;
      const [a, b] = t.value.split(':');
      return { kind: 'range', start: a.toUpperCase(), end: b.toUpperCase() };
    }
    return this.expr();
  }
}

export function parseFormula(src: string): Node {
  return new Parser(tokenize(src)).parse();
}

export function collectRefs(node: Node, into: Set<string>): void {
  switch (node.kind) {
    case 'ref':
      into.add(node.cell);
      break;
    case 'range':
      for (const c of expandRange(node.start, node.end)) into.add(c);
      break;
    case 'unary':
      collectRefs(node.arg, into);
      break;
    case 'bin':
      collectRefs(node.left, into);
      collectRefs(node.right, into);
      break;
    case 'call':
      for (const a of node.args) collectRefs(a, into);
      break;
  }
}

// --------------------------------------------------------- Cell coordinates

const COL_RE = /^([A-Za-z]+)([0-9]+)$/;

export function parseCellRef(ref: string): { col: number; row: number } {
  const m = ref.match(COL_RE);
  if (!m) throw new Error(`Invalid cell reference: ${ref}`);
  let col = 0;
  for (const ch of m[1].toUpperCase()) col = col * 26 + (ch.charCodeAt(0) - 64);
  return { col: col - 1, row: Number(m[2]) - 1 };
}

export function makeCellRef(col: number, row: number): string {
  let s = '';
  col += 1;
  while (col > 0) {
    const rem = (col - 1) % 26;
    s = String.fromCharCode(65 + rem) + s;
    col = Math.floor((col - 1) / 26);
  }
  return `${s}${row + 1}`;
}

export function expandRange(start: string, end: string): string[] {
  const a = parseCellRef(start);
  const b = parseCellRef(end);
  const cells: string[] = [];
  for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) {
    for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++) {
      cells.push(makeCellRef(c, r));
    }
  }
  return cells;
}

// ------------------------------------------------------------ Sheet engine

interface Cell {
  raw: string; // raw user input ('' = empty)
  ast: Node | null; // null for literals
  deps: Set<string>; // cells this cell reads from
  dependents: Set<string>; // cells that read from this cell
  value: EvalResult | undefined; // cached result; undefined = dirty
}

export interface Sheet {
  /** Set a cell's raw input: a literal ("42", "hello") or a formula ("=A1*2"). */
  set(cellRef: string, raw: string): void;
  /** Get the computed value of a cell (number/string/boolean or error object). */
  get(cellRef: string): EvalResult;
  /** Number of cells recomputed during the most recent set() call. */
  getRecomputeCount(): number;
}

export function createSheet(): Sheet {
  const cells = new Map<string, Cell>();
  let recomputeCount = 0;

  function ensure(ref: string): Cell {
    let c = cells.get(ref);
    if (!c) {
      c = { raw: '', ast: null, deps: new Set(), dependents: new Set(), value: undefined };
      cells.set(ref, c);
    }
    return c;
  }

  function isFormula(raw: string): boolean {
    return raw.trimStart().startsWith('=');
  }

  /**
   * Memoized recursive evaluation. `seen` is the active computation path
   * (insertion-ordered); re-entering a ref on it reveals a cycle, whose
   * members are exactly the suffix of the path starting at that ref.
   */
  function compute(ref: string, seen: Set<string>): EvalResult {
    const cell = cells.get(ref);
    if (!cell || cell.raw === '') return '';
    if (cell.value !== undefined) return cell.value;

    if (cell.ast === null) {
      cell.value = parseLiteral(cell.raw);
      recomputeCount++;
      return cell.value;
    }

    if (seen.has(ref)) {
      // Cycle found: stamp every member (path suffix from `ref`) with CYCLE.
      for (const member of seen) {
        ensure(member).value = CYCLE;
        if (member === ref) break; // insertion order => suffix from ref
      }
      return CYCLE;
    }

    seen.add(ref);
    const result = evaluate(cell.ast, seen);
    seen.delete(ref);
    cell.value = result;
    recomputeCount++;
    return result;
  }

  function evaluate(node: Node, seen: Set<string>): EvalResult {
    switch (node.kind) {
      case 'num':
        return node.value;
      case 'ref':
        return numeric(compute(node.cell, seen));
      case 'unary': {
        const v = numeric(evaluate(node.arg, seen));
        return isErr(v) ? v : node.op === '-' ? -v : v;
      }
      case 'bin': {
        const l = numeric(evaluate(node.left, seen));
        if (isErr(l)) return l;
        const r = numeric(evaluate(node.right, seen));
        if (isErr(r)) return r;
        switch (node.op) {
          case '+': return l + r;
          case '-': return l - r;
          case '*': return l * r;
          case '/': return r === 0 ? DIV0 : l / r;
        }
        break; // unreachable
      }
      case 'call': {
        const vals: number[] = [];
        for (const a of node.args) {
          if (a.kind === 'range') {
            for (const refName of expandRange(a.start, a.end)) {
              const v = compute(refName, seen);
              if (isErr(v)) return v;
              // blank/text cells inside ranges are ignored (spreadsheet semantics)
              if (typeof v === 'number') vals.push(v);
              else if (!isErr(v) && typeof v === 'boolean') vals.push(v ? 1 : 0);
            }
          } else {
            const v = numeric(evaluate(a, seen));
            if (isErr(v)) return v;
            vals.push(v);
          }
        }
        switch (node.fn) {
          case 'SUM': return vals.reduce((x, y) => x + y, 0);
          case 'AVG': return vals.length === 0 ? 0 : vals.reduce((x, y) => x + y, 0) / vals.length;
          case 'MIN': return vals.length === 0 ? 0 : Math.min(...vals);
          case 'MAX': return vals.length === 0 ? 0 : Math.max(...vals);
        }
        break; // unreachable
      }
    }
    throw new Error('Unreachable AST node');
  }

  /** Coerce a value to a number for arithmetic, passing errors through. */
  function numeric(v: EvalResult): number | CycleError | Div0Error {
    if (isErr(v)) return v;
    if (typeof v === 'number') return v;
    if (typeof v === 'boolean') return v ? 1 : 0;
    if (v === '') return 0;
    const n = Number(v);
    return Number.isNaN(n) ? 0 : n;
  }

  /** All transitive dependents of `ref` under the CURRENT graph edges. */
  function transitiveDependents(ref: string): string[] {
    const out: string[] = [];
    const vis = new Set<string>([ref]);
    const stack = [ref];
    while (stack.length) {
      const cur = stack.pop()!;
      for (const dep of cells.get(cur)?.dependents ?? []) {
        if (!vis.has(dep)) {
          vis.add(dep);
          out.push(dep);
          stack.push(dep);
        }
      }
    }
    return out;
  }

  const api: Sheet = {
    set(ref, raw) {
      ref = ref.toUpperCase();
      const cell = ensure(ref);

      // Snapshot the affected region BEFORE rewiring edges: everything
      // downstream of this cell (old edges included) may become dirty.
      const dirty = transitiveDependents(ref);

      // Rewire outgoing dependency edges.
      for (const d of cell.deps) cells.get(d)?.dependents.delete(ref);
      cell.deps.clear();

      cell.raw = raw;
      cell.value = undefined; // dirty

      if (isFormula(raw)) {
        try {
          cell.ast = parseFormula(raw.trimStart().slice(1));
          collectRefs(cell.ast, cell.deps);
          for (const d of cell.deps) ensure(d).dependents.add(ref);
        } catch {
          cell.ast = null;
          cell.value = '#PARSE_ERROR';
        }
      } else {
        cell.ast = null;
      }

      recomputeCount = 0;
      // Recompute the edited cell plus its (possibly changed) downstream set.
      compute(ref, new Set());
      for (const d of [...transitiveDependents(ref), ...dirty]) {
        if (cells.get(d)?.value === undefined) compute(d, new Set());
      }
    },

    get(ref) {
      ref = ref.toUpperCase();
      const cell = cells.get(ref);
      if (!cell || cell.raw === '') return '';
      if (cell.value !== undefined) return cell.value;
      return compute(ref, new Set()); // lazy fallback
    },

    getRecomputeCount() {
      return recomputeCount;
    },
  };

  return api;
}

function parseLiteral(raw: string): EvalResult {
  const trimmed = raw.trim();
  if (trimmed === '') return '';
  if (/^-?\d+(\.\d+)?$/.test(trimmed)) return Number(trimmed);
  if (trimmed.toLowerCase() === 'true') return true;
  if (trimmed.toLowerCase() === 'false') return false;
  return trimmed;
}
